    '<button class="к-шапка" data-ст-нав="след" aria-label="Следующая статья"><svg class="и" style="transform:scaleX(-1)" aria-hidden="true"><use href="#и-назад"/></svg></button>'+
    '</header>'+
    '<div class="лист-тело статья-тело"><p class="ист-пусто">Загружаю статью…</p></div>';
