function показатьВариант(к){
  var в = document.getElementById('ваш-вариант'); if(!в) return;
  if(!к){ в.innerHTML = ''; в.className = ''; return; }
  var естьВзять = !!(листСтатья && листСтатья.querySelector('.ст-взять'));
  в.className = 'ваш-вариант к-'+к;
  в.innerHTML = '<div class="вв-шапка"><span class="бук">'+к+'</span><div><small>Если врач подтвердит</small><b>Категория '+к+': '+э(КАТ_ИМЯ[к].toLowerCase())+'</b></div></div>'+
    '<p class="вв-смысл">'+э(КАТ_СМЫСЛ[к])+'</p>'+
    '<h4>Что делать дальше</h4><ol class="вв-шаги">'+
      '<li>'+э(ДАЛЬШЕ_ПО_КАТЕГОРИИ[к])+'</li>'+
      '<li>Если решение комиссии не устраивает, его можно оспорить: раздел «Бумаги».</li>'+
      '<li>Сохраните статью в «моё дело», чтобы не потерять.</li></ol>'+
    '<div class="вв-кнопки">'+(естьВзять ? '<button class="кнопка гх" data-что-взять>Что взять к врачу</button>' : '')+
      '<button class="кнопка гх" data-бумага="1">Не согласен с решением</button></div>'+
    '<p class="вв-оговорка">Категорию назначает призывная комиссия по документам врачей. Это справка по тексту Расписания болезней.</p>';
  setTimeout(function(){
    var к0 = в.closest('.лист-тело'); if(!к0) return;
    var сдвиг = в.getBoundingClientRect().top - к0.getBoundingClientRect().top;
    к0.scrollTo({top: к0.scrollTop + сдвиг - 90, behavior:'smooth'});
  }, 60);
}
function показатьРешение(){
  показатьВариант(выбраннаяКат);
  var р = document.getElementById('реш'); if(!р) return;
  р.hidden = true; р.className = 'реш'; р.innerHTML = ''; return;  /* прежняя нижняя плашка заменена карточкой «Ваш вариант» в тексте */
  if(!выбраннаяКат){ р.hidden = true; р.className = 'реш'; р.innerHTML = ''; return; }
  var к = выбраннаяКат;
  р.className = 'реш к-'+к; р.hidden = false;
  р.innerHTML = '<span class="бук">'+к+'</span><div><b>Если врач подтвердит — категория '+к+': '+КАТ_ИМЯ[к].toLowerCase()+'</b><span>'+КАТ_СМЫСЛ[к]+' Категорию назначает врач по документам.</span></div>';
}
function спроситьСтатью(){
  var в = document.getElementById('вопрос-статье'), о = document.getElementById('ответ-статьи');
  if(!в || !о || !статьяИд) return;
  var текст = в.value.trim(); if(!текст) return;
  о.innerHTML = '<p class="ответ-строка тише">Читаю статью…</p>';
  fetch('/api/читатель', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ид:статьяИд, вопрос:текст})})
    .then(function(р){ return р.json(); })
    .then(function(д){
      if(д.ошибка){ о.innerHTML = '<p class="ответ-строка ош">'+э(д.ошибка)+'</p>'; return; }
      о.innerHTML = '<p class="ответ-строка">'+э(д.ответ)+'</p>'+(д.цитаты || []).map(function(ц){
        return '<div class="цитата">«'+э(ц.текст)+'»<i>'+(ц.подтверждена ? '✓ есть в статье' : 'не найдена')+'</i></div>';
      }).join('');
    }).catch(function(){ о.innerHTML = '<p class="ответ-строка ош">Сервер не ответил: для вопроса по статье нужна модель на сервере.</p>'; });
}

