function главаИз(ид){
  var н = parseInt(ид, 10);
  if(isNaN(н)) return null;
  for(var i = 0; i < ГЛАВЫ.length; i++){ if(н >= ГЛАВЫ[i].а && н <= ГЛАВЫ[i].б) return ГЛАВЫ[i]; }
  return null;
}

function просто(н){
  var части = String(н || '').split(',').map(function(т){ return т.trim(); }).filter(Boolean);
  if(!части.length) return '';
  var т = части[0];
  for(var i = 1; i < части.length && т.length < 16; i++){
    if((т + ', ' + части[i]).length > 40) break;
    т = т + ', ' + части[i];
  }
  if(т.length > 46){
    var срез = т.slice(0, 46);
    var пробел = срез.lastIndexOf(' ');
    if(пробел > 24) т = срез.slice(0, пробел).replace(/[—–-]+$/, '').trim() + '…';
  }
  return т;
}

function ваша(){
  return (состояние.итог && состояние.итог.рейтинг && состояние.итог.рейтинг[0]) ? String(состояние.итог.рейтинг[0].статья) : '';
}
function вДеле(ид){
  if(!ид) return false;
  for(var i = 0; i < дело.length; i++){ if(String(дело[i].ид) === String(ид)) return true; }
  return false;
}
function записьДела(ид){
  if(!ид) return null;
  for(var i = 0; i < дело.length; i++){ if(String(дело[i].ид) === String(ид)) return дело[i]; }
  return null;
}
function мояСтатья(ид){
  return !!ид && (вДеле(ид) || ваша() === String(ид));
}
function добавитьВДело(ид, статус){
  if(!ид || вДеле(ид)) return;
  дело.unshift({ид:String(ид), статус: статус === 'врач' ? 'врач' : 'слово', в: Date.now(), шагЗакрыт:false});
  записатьДело();
  обновитьТочкуДела();
  if(режим === 'дело' && экранДело) заполнитьДело();
  тост('Добавлено в дело');
}
function убратьИзДела(ид){
  var с = String(ид);
  дело = дело.filter(function(з){ return String(з.ид) !== с; });
  записатьДело();
  обновитьТочкуДела();
  if(режим === 'дело' && экранДело) заполнитьДело();
  тост('Убрано из дела');
}
var тостТайм = null;
function тост(текст){
  if(!вкл('тосты')) return;
  var б = document.getElementById('тост');
  if(!б){
    б = document.createElement('div');
    б.id = 'тост';
    б.className = 'тост';
    б.setAttribute('role', 'status');
    (document.querySelector('.телефон') || document.body).appendChild(б);
  }
  б.textContent = текст;
  б.classList.add('он');
  clearTimeout(тостТайм);
  тостТайм = setTimeout(function(){ б.classList.remove('он'); }, 1900);
}
function качнутьДело(ид, статус){
  if(вДеле(ид)) убратьИзДела(ид); else добавитьВДело(ид, статус);
}
function незакрытаяЗапись(){
  for(var i = 0; i < дело.length; i++){ if(!дело[i].шагЗакрыт) return дело[i]; }
  return null;
}
function обновитьТочкуДела(){
  var точ = !!незакрытаяЗапись();
  document.querySelectorAll('.режим[data-режим="дело"]').forEach(function(б){
    б.classList.toggle('есть-точка', точ);
    if(точ) б.setAttribute('aria-label', 'Дело — есть незакрытый шаг');
    else б.removeAttribute('aria-label');
  });
}

var ПОРЯДОК_ГРАФ = ['А','Б','В','Г','Д'];
function графаПервая(г){
  var с = String(г || '').trim().toUpperCase(), н = parseInt(с, 10);
  if(!isNaN(н) && н >= 1 && н <= ПОРЯДОК_ГРАФ.length) return ПОРЯДОК_ГРАФ[н-1];
  for(var i = 0; i < ПОРЯДОК_ГРАФ.length; i++){ if(с.indexOf(ПОРЯДОК_ГРАФ[i]) === 0) return ПОРЯДОК_ГРАФ[i]; }
  return с.charAt(0) || null;
}

function диапазон(ид){
  var д = графыЛишь[String(ид)];
  if(!д || !д.мин) return '';
  if(д.мин === д.макс) return д.мин;
  return д.мин + ' — ' + д.макс;
}

function поНомеру(а, б){ return parseInt(а.ид, 10) - parseInt(б.ид, 10); }

function подкачатьГрафы(){
  if(!СтатьиКаталог) return;
  var обещания = СтатьиКаталог.map(function(с){
    var и = String(с.ид);
    if(графыЛишь[и]) return null;
    return запросСтатьи(и).then(function(а){
      var графы = [], ключи = {};
      (((а && а.пункты) || [])).forEach(function(п){
        var г = (п.графы || [])[0];
        г = г == null ? '' : String(г).trim();
        if(!г || ключи[г]) return;
        ключи[г] = true;
        графы.push(г);
      });
      if(!графы.length) return;
      графы.sort(function(х, у){
        var ох = ПОРЯДОК_ГРАФ.indexOf(графаПервая(х)), оу = ПОРЯДОК_ГРАФ.indexOf(графаПервая(у));
        if(ох !== оу) return ох - оу;
        return х.localeCompare(у, 'ru');
      });
      графыЛишь[и] = {мин:графы[0], макс:графы[графы.length-1]};
    }).catch(function(){});
  }).filter(Boolean);
  if(!обещания.length) return;
  Promise.all(обещания).then(function(){
    if(document.documentElement.getAttribute('data-режим') === 'документация') отрисоватьДок();
  });
}

