var КАТЕГОРИИ = ['А','Б','В','Г','Д'];
var КАТ_ИМЯ = {А:'Годен', Б:'Годен с незначительными ограничениями', В:'Ограниченно годен', Г:'Временно не годен', Д:'Не годен'};
var КАТ_СМЫСЛ = {
  А:'Годен к службе без ограничений.',
  Б:'Служба возможна, с учётом ограничений.',
  В:'Освобождение от призыва в мирное время.',
  Г:'Отсрочка от призыва, обычно до 12 месяцев.',
  Д:'Исключение с воинского учёта.'
};

function статьяДанные(ид){
  var в = window.СПРАВОЧНИК_ДАННЫЕ;
  return (в && в.статьи && в.статьи[String(ид)]) || null;
}
function буквуГрафы(г){
  var м = /^[АБВГД]/.exec(String(г || '').trim().toUpperCase());
  return м ? м[0] : null;
}
function счётКатегорий(ид){
  var с = {А:0, Б:0, В:0, Г:0, Д:0}, а = статьяДанные(ид);
  if(а) (а.пункты || []).forEach(function(п){ var б = буквуГрафы((п.графы || [])[0]); if(б) с[б]++; });
  return с;
}
function htmlПолоса(с, крупная){
  return '<span class="полоса'+(крупная ? ' крупная' : '')+'" aria-hidden="true">'+КАТЕГОРИИ.map(function(к){
    return '<i class="к-'+к+(с[к] ? ' есть' : '')+'"></i>';
  }).join('')+'</span>';
}
function счётСписка(идыМас){
  var с = {А:0, Б:0, В:0, Г:0, Д:0};
  идыМас.forEach(function(ид){ var к = счётКатегорий(ид); КАТЕГОРИИ.forEach(function(б){ с[б] += к[б]; }); });
  return с;
}
function идыГлавыПоИмени(имя){
  var г = ГЛАВЫ.filter(function(х){ return х.имя === имя; })[0];
  if(!г) return [];
  return (СтатьиКаталог || []).filter(function(с){ var н = parseInt(с.ид, 10); return н >= г.а && н <= г.б; }).sort(поНомеру);
}
/* ===== Бланк «Справка по запросу»: поле «Жалобы», кирпичи сборки, графы; заполняет ядро NNL ===== */
function сегодняСтрокой(){
  var д = new Date();
  return ('0'+д.getDate()).slice(-2)+'.'+('0'+(д.getMonth()+1)).slice(-2)+'.'+д.getFullYear();
}
function htmlБланк(){
  return '<section class="бланк" id="бланк">'+
    '<div class="бл-шапка"><span>Справка по запросу</span><time>'+сегодняСтрокой()+'</time></div>'+
    '<label class="бл-ввод" for="рс-фильтр"><small>Жалобы — своими словами</small><span class="бл-ряд-ввода"><textarea id="рс-фильтр" rows="1" autocomplete="off" spellcheck="false" enterkeyhint="search" placeholder="Например: колет сердце" aria-label="Что беспокоит"></textarea>'+
      '<button type="button" class="бл-очист" data-бл-очистить hidden aria-label="Очистить">'+и('и-крест')+'</button></span></label>'+
    '<div class="полка бл-кирпичи" id="бл-кирпичи"></div>'+
    '<dl class="бл-поля" id="бл-поля"></dl>'+
    '<div id="бл-действие"></div>'+
  '</section>';
}
