function свод_часы(){
  var риски = '';
  for(var h = 0; h < 24; h++){
    var а = (h / 24) * Math.PI * 2 - Math.PI / 2, r1 = h % 6 === 0 ? 50 : 54, r2 = 58;
    риски += '<line x1="'+(150 + Math.cos(а) * r1).toFixed(1)+'" y1="'+(75 + Math.sin(а) * r1).toFixed(1)+'" x2="'+(150 + Math.cos(а) * r2).toFixed(1)+'" y2="'+(75 + Math.sin(а) * r2).toFixed(1)+'"/>';
  }
  var a9 = (9 / 24) * Math.PI * 2 - Math.PI / 2, a21 = (21 / 24) * Math.PI * 2 - Math.PI / 2, R = 44;
  var дуга = 'M'+(150 + Math.cos(a9) * R).toFixed(1)+' '+(75 + Math.sin(a9) * R).toFixed(1)+' A'+R+' '+R+' 0 0 1 '+(150 + Math.cos(a21) * R).toFixed(1)+' '+(75 + Math.sin(a21) * R).toFixed(1);
  return '<g class="риски">'+риски+'</g><path class="дуга" d="'+дуга+'"/><text x="150" y="80" text-anchor="middle" class="крупно">09–21</text>';
}
