function htmlСводка(){
  var карточки = СВОДКА.map(function(к, i){
    var внутр = '<span class="свод-арт арт-'+к.арт+'" aria-hidden="true">'+СВОДКА_АРТ[к.арт]+'</span>'+
      '<span class="свод-в">'+
      '<span class="свод-верх"><span class="свод-метка">'+э(к.метка)+'</span><span class="свод-номер">'+(i + 1)+'/'+СВОДКА.length+'</span></span>'+
      '<b class="свод-заг">'+э(к.заг)+'</b>'+
      '<span class="свод-текст">'+э(к.текст)+'</span>'+
      (к.действие ? '<span class="свод-деист">'+э(к.действие)+'<i>'+(к.ссылка && к.ссылка.indexOf('tel:') === 0 ? '' : '↗')+'</i></span>' : '')+
    '</span>';
    var внешняя = к.ссылка && к.ссылка.indexOf('http') === 0;
    var общее = ' class="свод-кар вид-'+к.вид+'" style="--i:'+i+'" draggable="false"';
    return к.ссылка
      ? '<a'+общее+' href="'+к.ссылка+'"'+(внешняя ? ' target="_blank" rel="noopener noreferrer"' : '')+'>'+внутр+'</a>'
      : '<div'+общее+'>'+внутр+'</div>';
  }).join('');
  var точки = СВОДКА.map(function(_, i){ return '<button type="button" class="свод-т'+(i === 0 ? ' акт' : '')+'" data-свод="'+i+'" aria-label="Карточка '+(i + 1)+'"><i></i></button>'; }).join('');
  return '<div class="свод" id="свод" aria-label="Сводка"><div class="свод-лента" id="свод-лента">'+карточки+'</div><div class="свод-точки" id="свод-точки">'+точки+'</div></div>';
}
(function(){
  var тек = 0, держат = 0, мышь = {вниз:false, x0:0, s0:0, сдвиг:0};
  var снижение = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function эл(){ return {св:document.getElementById('свод'), лн:document.getElementById('свод-лента')}; }
  function кСередине(лн, к){ return к.offsetLeft - (лн.clientWidth - к.offsetWidth) / 2; }
  function к(н){
    var э0 = эл(); if(!э0.лн) return;
    var кар = э0.лн.querySelectorAll('.свод-кар');
    н = (н + кар.length) % кар.length;
    э0.лн.scrollTo({left: кСередине(э0.лн, кар[н]), behavior: снижение ? 'auto' : 'smooth'});
  }
  /* Размер, прозрачность и лёгкий параллакс карточек считаются от расстояния до центра ленты, пока идёт скролл */
  var ждём = false;
  function разметить(){
    ждём = false;
    var э0 = эл(); if(!э0.лн) return;
    var лн = э0.лн, ц = лн.scrollLeft + лн.clientWidth / 2, лучш = 0, мин = 1e9;
    var кар = лн.querySelectorAll('.свод-кар');
    Array.prototype.forEach.call(кар, function(е, i){
      var с = (е.offsetLeft + е.offsetWidth / 2 - ц) / (е.offsetWidth * 0.9);
      var д = Math.min(1, Math.abs(с));
      е.style.setProperty('--д', д.toFixed(3));
      е.style.setProperty('--с', Math.max(-1, Math.min(1, с)).toFixed(3));
      if(Math.abs(с) < мин){ мин = Math.abs(с); лучш = i; }
    });
    if(лучш !== тек){
      тек = лучш;
      Array.prototype.forEach.call(э0.св.querySelectorAll('.свод-т'), function(т, i){ т.classList.toggle('акт', i === тек); });
    }
  }
  function запросить(){ if(!ждём){ ждём = true; requestAnimationFrame(разметить); } }
  document.addEventListener('scroll', function(e){ if(e.target && e.target.id === 'свод-лента') запросить(); }, true);
  window.addEventListener('resize', запросить);
  /* пауза, пока человек держит ленту: и на касание, и на мышь */
  function пауза(вкл){
    var э0 = эл(); if(!э0.св) return;
    держат = Math.max(0, держат + (вкл ? 1 : -1));
    э0.св.classList.toggle('пауза', держат > 0);
  }
  document.addEventListener('pointerdown', function(e){
    var лн = e.target.closest && e.target.closest('#свод-лента'); if(!лн) return;
    пауза(true);
    if(e.pointerType === 'mouse'){
      мышь = {вниз:true, x0:e.clientX, s0:лн.scrollLeft, сдвиг:0};
      лн.classList.add('тянут');
    }
  });
  document.addEventListener('pointermove', function(e){
    if(!мышь.вниз) return;
    var лн = document.getElementById('свод-лента'); if(!лн) return;
    мышь.сдвиг = e.clientX - мышь.x0;
    лн.scrollLeft = мышь.s0 - мышь.сдвиг;
  });
  function отпустить(){
    var э0 = эл();
    if(мышь.вниз && э0.лн){
      мышь.вниз = false;
      э0.лн.classList.remove('тянут');
      var кар = э0.лн.querySelectorAll('.свод-кар'), н = тек;
      if(Math.abs(мышь.сдвиг) > 40 && н === тек) н = мышь.сдвиг < 0 ? Math.min(кар.length - 1, тек + 1) : Math.max(0, тек - 1);
      к(н);
    }
    if(держат > 0) setTimeout(function(){ пауза(false); }, 1500);
  }
  document.addEventListener('pointerup', отпустить);
  document.addEventListener('pointercancel', отпустить);
  /* после перетаскивания мышью ссылка не должна открываться */
  document.addEventListener('click', function(e){
    var а = e.target.closest && e.target.closest('.свод-кар');
    if(а && Math.abs(мышь.сдвиг) > 6){ e.preventDefault(); мышь.сдвиг = 0; }
    var т = e.target.closest && e.target.closest('[data-свод]');
    if(т){ к(parseInt(т.getAttribute('data-свод'), 10)); }
  }, true);
  /* заполнение активной точки закончилось: листаем дальше */
  document.addEventListener('animationend', function(e){
    if(e.animationName === 'свод-заливка' && !снижение) к(тек + 1);
  }, true);
  setTimeout(запросить, 60);
  new MutationObserver(function(){ запросить(); }).observe(document.body, {childList:true, subtree:true});
})();
function обновитьСчёт(){ /* число и шкала убраны по просьбе; пустой верх */
  var в = document.getElementById('вход-верх'); if(!в) return;
  в.hidden = докТема !== 'вход' && !рсФильтр.trim();
  в.classList.toggle('сжат', !!рсФильтр.trim());
  подогнатьВход();
}
