/* Бланк: рост поля, очистка, кнопка «к полю запроса», открытие статьи с пунктом */
(function(){
  function размер(в){ в.style.height = 'auto'; в.style.height = Math.min(в.scrollHeight, 150) + 'px'; }
  document.addEventListener('input', function(e){ if(e.target && e.target.id === 'рс-фильтр') размер(e.target); });
  document.addEventListener('keydown', function(e){
    if(e.target && e.target.id === 'рс-фильтр' && e.key === 'Enter'){ e.preventDefault(); e.target.blur(); }
  });
  document.addEventListener('click', function(e){
    var т = e.target; if(!т.closest) return;
    if(т.closest('[data-бл-очистить]')){
      var в = document.getElementById('рс-фильтр'); if(!в) return;
      в.value = ''; в.dispatchEvent(new Event('input', {bubbles:true})); размер(в); в.focus(); return;
    }
    if(т.closest('#к-поиск')){
      var ст = document.getElementById('поиск-строка'), вв = document.getElementById('поиск-ввод');
      var открыто = ст.classList.contains('открыта');
      ст.classList.toggle('открыта', !открыто);
      setTimeout(обновитьБланк, 0);
      document.getElementById('к-поиск').classList.toggle('открыт', !открыто);
      if(!открыто){ setTimeout(function(){ вв.focus(); }, 200); }
      else { вв.blur(); вв.value = ''; вв.dispatchEvent(new Event('input', {bubbles:true})); }
      return;
    }
    if(т.closest('[data-опишите]')){
      var ст0 = document.getElementById('поиск-строка');
      if(ст0 && !ст0.classList.contains('открыта')){ document.getElementById('к-поиск').click(); }
      else { var в0 = document.getElementById('поиск-ввод'); if(в0) в0.focus(); }
      return;
    }
    if(т.closest('#поиск-очист')){
      var в3 = document.getElementById('поиск-ввод'); в3.value = ''; в3.dispatchEvent(new Event('input', {bubbles:true})); в3.focus(); return;
    }
    var ок = т.closest('[data-открыть-бланк]');
    if(ок){ открытьСтатью(ок.getAttribute('data-открыть-бланк'), 'каталог', ок.hasAttribute('data-пункт') ? {пункт: ок.getAttribute('data-пункт')} : null); return; }
  });
  /* «тяжёлый» переход между пустым верхом и областями: колесо и жест двигают экран медленно, с торможением */
  var тяж = {идёт:false, y0:0, s0:0, drag:false};
  function граница(){ var в = document.getElementById('вход-верх'); return (в && !в.hidden && !в.classList.contains('сжат')) ? в.offsetHeight : 0; }
  function тяжёлыйСкролл(цель){
    var от = экранДок.scrollTop, т0 = performance.now(), длит = 1100;
    тяж.идёт = true;
    (function шаг(т){
      var п = Math.min(1, (т - т0) / длит);
      var е = п < .5 ? 8*п*п*п*п : 1 - Math.pow(-2*п + 2, 4) / 2;
      экранДок.scrollTop = от + (цель - от) * е;
      if(п < 1) requestAnimationFrame(шаг); else тяж.идёт = false;
    })(т0);
  }
  экранДок.addEventListener('wheel', function(e){
    var гр = граница(); if(!гр) return;
    if(тяж.идёт){ e.preventDefault(); return; }
    var т = экранДок.scrollTop;
    if(e.deltaY > 0 && т < гр - 2){ e.preventDefault(); тяжёлыйСкролл(гр); }
    else if(e.deltaY < 0 && т > 0 && т <= гр + 2){ e.preventDefault(); тяжёлыйСкролл(0); }
  }, {passive:false});
  экранДок.addEventListener('touchstart', function(e){
    var гр = граница(); if(!гр || тяж.идёт) return;
    var т = экранДок.scrollTop;
    тяж.drag = т <= гр + 2;
    тяж.y0 = e.touches[0].clientY; тяж.s0 = т;
  }, {passive:true});
  экранДок.addEventListener('touchmove', function(e){
    var гр = граница(); if(!гр || !тяж.drag || тяж.идёт) return;
    var dy = e.touches[0].clientY - тяж.y0;
    var н = тяж.s0 - dy * 0.4; /* палец тянет в 2,5 раза медленнее: ощущение веса */
    if(н >= гр && dy < 0 && тяж.s0 >= гр) { тяж.drag = false; return; }
    e.preventDefault();
    экранДок.scrollTop = Math.max(0, Math.min(гр, н));
  }, {passive:false});
  экранДок.addEventListener('touchend', function(){
    var гр = граница(); if(!гр || !тяж.drag || тяж.идёт) return;
    тяж.drag = false;
    var т = экранДок.scrollTop;
    if(т > 0 && т < гр) тяжёлыйСкролл(т > гр * 0.3 ? гр : 0);
  }, {passive:true});
  /* верх тает и сдвигается медленнее, чем едет экран: параллакс даёт тяжесть */
  экранДок.addEventListener('scroll', function(){
    var в = document.getElementById('вход-верх'); if(!в) return;
    var п = Math.min(1, экранДок.scrollTop / Math.max(1, в.offsetHeight));
    в.style.opacity = String(1 - п * 0.9);
    в.style.transform = 'translateY('+(экранДок.scrollTop * 0.35)+'px)';
  }, {passive:true});
  /* скролл вниз раскрывает шарик в панель поиска, вверх сворачивает обратно в шарик */
  var посл = 0, накоп = 0;
  function поискРаскрыть(да){
    var ст = document.getElementById('поиск-строка'), з = document.getElementById('к-поиск');
    if(!ст || ст.classList.contains('открыта') === да) return;
    ст.classList.toggle('открыта', да); з.classList.toggle('открыт', да);
  }
  экранДок.addEventListener('scroll', function(){
    var т = экранДок.scrollTop, д = т - посл;
    var пв2 = document.getElementById('поиск-ввод');
    посл = т;
    if(performance.now() < поискБлок){ накоп = 0; return; }   /* смена экрана сбрасывает прокрутку: не реагируем */
    if(д * накоп < 0) накоп = 0;                               /* направление сменилось: копим заново */
    накоп += д;
    if(накоп > 90 && т > 40) { поискРаскрыть(true); накоп = 0; }
    else if(накоп < -120 && !(пв2 && (пв2.value || document.activeElement === пв2))) { поискРаскрыть(false); накоп = 0; }
  }, {passive:true});
  var пв = document.getElementById('поиск-ввод');
  if(пв){
    пв.addEventListener('input', function(){
      рсФильтр = пв.value;
      document.getElementById('поиск-очист').hidden = !пв.value;
      запуститьУмныйПоиск();
      отрисоватьДок();
      экранДок.scrollTop = 0;
    });
    пв.addEventListener('keydown', function(e){ if(e.key === 'Enter'){ e.preventDefault(); пв.blur(); } });
  }
})();


/* Бумаги: шаги мастера */
(function(){
  function шаг(д){
    var н = текущаяБумага; if(н === null) return;
    var всего = разобратьБумагу(н).поля.length;
    бумШаг = Math.max(0, Math.min(всего, бумШаг + д));
    перерисоватьМастер(true);
  }
  document.addEventListener('click', function(e){
    var т = e.target; if(!т.closest || текущаяБумага === null || !листСтатья.contains(т)) return;
    if(т.closest('[data-закрыть]') && режим === 'бумаги'){
      var пр = экранБу.scrollTop; заполнитьБумаги(); экранБу.scrollTop = пр; return;
    }
    var к = т.closest('[data-бум-к]');
    if(к){ бумШаг = parseInt(к.getAttribute('data-бум-к'), 10) || 0; перерисоватьМастер(true); return; }
    if(т.closest('[data-бум-дальше]')){ шаг(1); return; }
    if(т.closest('[data-бум-назад]')){ шаг(-1); return; }
  });
  document.addEventListener('input', function(e){
    var в = e.target; if(!в.getAttribute || текущаяБумага === null) return;
    var и = в.getAttribute('data-бум-зн'); if(и === null) return;
    var х = хранилищеБумаги(текущаяБумага);
    х.в[и] = в.value; delete х.а[и];
    записатьБумагу(текущаяБумага, х);
    var точка = листСтатья.querySelector('.бум-т.тек');
    if(точка) точка.classList.toggle('зап', !!String(в.value).trim());
    var кн = листСтатья.querySelector('[data-бум-дальше]');
    var всего = разобратьБумагу(текущаяБумага).поля.length;
    if(кн && бумШаг < всего-1) кн.textContent = String(в.value).trim() ? 'Далее' : 'Пропустить';
    var ав = листСтатья.querySelector('.бум-авто'); if(ав) ав.remove();
    обновитьДокумент();
  });
  document.addEventListener('change', function(e){
    var в = e.target;
    if(в && в.getAttribute && в.getAttribute('data-бум-зн') !== null && в.type === 'date') в.dispatchEvent(new Event('input', {bubbles:true}));
  });
  document.addEventListener('keydown', function(e){
    var в = e.target;
    if(e.key === 'Enter' && в && в.getAttribute && в.getAttribute('data-бум-зн') !== null && в.tagName === 'INPUT'){ e.preventDefault(); шаг(1); }
  });
})();


